const DRILLS_I18N={
  en:{"d-squat":{"name":"Bodyweight Squat","mus":"Legs · Glutes","cue":"Knees tracking over toes, chest up, descend to 90°.","easy":"Box squat — touch the bench and stand up.","hard":"Jump squat, or a 3-second slow descent."},"d-push":{"name":"Push-ups","mus":"Chest · Arms · Core","cue":"Body like a straight board — hips don't sag or pike.","easy":"Hands on a bench or wall — the higher, the easier.","hard":"Close-grip, or a 2-second pause at the bottom."},"d-lunge":{"name":"Walking Lunge","mus":"Legs · Balance","cue":"Both knees at 90°, torso upright, back knee gently clears the floor without slamming.","easy":"Stationary lunge with a hand on the wall for balance.","hard":"Jumping lunges, or holding a dumbbell."},"d-glute":{"name":"Glute Bridge","mus":"Glutes · Lower Back","cue":"Drive through the heels, squeeze glutes — no arching the lower back.","easy":"Shorter range of motion, hold for 1 second only.","hard":"Single leg, or a 3-second hold at the top."},"d-wall":{"name":"Wall Sit","mus":"Legs","cue":"Thighs parallel to the floor, back flat against the wall, hands off knees.","easy":"Higher angle — less knee bend.","hard":"Alternate lifting one leg every 5 seconds."},"d-step":{"name":"Bench Step-ups","mus":"Legs · Balance","cue":"Push from the foot on the bench — do not jump off the bottom foot.","easy":"Lower bench or step.","hard":"Step-up with a high knee drive at the top, or hold a dumbbell."},"d-dip":{"name":"Bench Dips","mus":"Triceps · Shoulders","cue":"Elbows point straight back and stay tucked, shoulders away from ears.","easy":"Knees bent, feet closer to the body.","hard":"Straight legs elevated on a second bench."},"d-pike":{"name":"Pike Push-ups","mus":"Shoulders","cue":"Hips high, head lowers between the hands.","easy":"Hips lower — closer to a standard push-up.","hard":"Feet on a bench — guided handstand progression."},"d-bear":{"name":"Bear Crawl","mus":"Full Body · Core","cue":"Knees hovering an inch off the floor, back flat.","easy":"Crawl on knees.","hard":"Crawl with a cup of water on the back — without spilling."},"d-calf":{"name":"Calf Raises","mus":"Calves","cue":"Slow ascent, 1-second pause at the top, controlled descent.","easy":"Both feet with a hand on the wall.","hard":"Single leg from the edge of a step."},"d-nordic":{"name":"Nordic Hamstring Curl (Pairs)","mus":"Hamstrings","cue":"Lower as slowly as possible, hands ready to catch. The premier exercise for reducing hamstring tears.","easy":"Short range — lower only 20°.","hard":"5-second descent to the floor."},"d-sldl":{"name":"Single-Leg Deadlift (Bodyweight)","mus":"Glutes · Balance","cue":"Body and back leg lower as one straight board, hips stay square.","easy":"Back toe touches the floor for balance.","hard":"Eyes closed, or hold a dumbbell in the opposite hand."},"d-goblet":{"name":"Goblet Squat","mus":"Legs · Core","cue":"Dumbbell close to the chest, elbows inside knees at the bottom.","easy":"Lighter weight or no weight at all.","hard":"2-second pause at the bottom."},"d-row":{"name":"Dumbbell Row","mus":"Back · Biceps","cue":"Elbow pulls back close to the body, squeeze the shoulder blade at the top.","easy":"Support with one hand on a bench.","hard":"Bent-over row with both hands, without support."},"d-press":{"name":"Shoulder Press","mus":"Shoulders · Triceps","cue":"Core tight — no arching the lower back.","easy":"Seated press with back support.","hard":"Alternating single-arm press — challenges the core."},"d-rdl":{"name":"Romanian Deadlift (RDL)","mus":"Glutes · Hamstrings","cue":"Hips hinge back, back stays straight — dumbbells slide down the legs.","easy":"Short range just to the knee.","hard":"Single leg, or a 2-second pause at the bottom."},"d-band":{"name":"Band Pull","mus":"Back · Biceps","cue":"The pull initiates from the shoulder blades, not the arms.","easy":"Lighter band or grip closer to the anchor.","hard":"Heavier band + 1-second pause at full contraction."},"d-pull":{"name":"Pull-up / Assisted Pull-up","mus":"Back · Biceps","cue":"Pull the chest to the bar, controlled descent to full extension.","easy":"Band assistance, or a 15-second isometric hang.","hard":"5-second slow descent (eccentric)."},"d-kb":{"name":"Kettlebell Swing","mus":"Glutes · Back · Core","cue":"Movement is from the hips, not the arms — explosive hip thrust.","easy":"Swing to chest height only, light weight.","hard":"American swing to overhead."},"d-carry":{"name":"Farmer's Walk","mus":"Core · Grip","cue":"Shoulders back and down, short steady steps.","easy":"Light weight and short distance.","hard":"Weight in one hand only — core works double."},"d-medball":{"name":"Medicine Ball Wall Throw","mus":"Full Body · Explosive Power","cue":"Power comes from the legs and hips — arms merely transfer it.","easy":"Lighter ball, chest pass only.","hard":"Rotational overhead throw, greater distance."},"d-plank":{"name":"Plank","mus":"Core · Shoulders","cue":"Elbows under shoulders, core braced, continuous breathing.","easy":"Plank on knees or elevated on a bench.","hard":"Alternate lifting one arm or leg every 5 seconds."},"d-splank":{"name":"Side Plank","mus":"Core · Obliques","cue":"Straight line from head to ankle — hips don't sag or stick out.","easy":"Bottom knee on the floor.","hard":"Lift top leg, or perform 10 hip dips."},"d-deadbug":{"name":"Dead Bug","mus":"Core · Stability","cue":"Lower back is glued to the floor throughout the entire movement.","easy":"Legs only, arms stay up.","hard":"4-second movement per rep."},"d-birddog":{"name":"Bird Dog","mus":"Core · Stability","cue":"Hips don't rotate — opposite arm and leg extend together.","easy":"Leg only, no arm.","hard":"3-second pause + elbow touches knee between reps."},"d-hollow":{"name":"Hollow Hold","mus":"Abs","cue":"Lower back glued to the floor — if it arches, shorten the lever.","easy":"Knees bent, arms by your sides.","hard":"Arms overhead with straight, low legs."},"d-bicycle":{"name":"Bicycle Crunches","mus":"Abs · Obliques","cue":"Elbow meets opposite knee slowly — no pulling on the neck.","easy":"Torso rotation only, feet on the floor.","hard":"3-second movement to each side."},"d-superman":{"name":"Superman","mus":"Lower Back","cue":"Lift arms and legs together, gaze at the floor — neck in line with the spine.","easy":"Opposite arm and leg only.","hard":"3-second hold on every rep."},"d-rtwist":{"name":"Russian Twist","mus":"Abs · Obliques","cue":"Rotation comes from the chest, not just moving the arms.","easy":"Feet on the floor, no ball.","hard":"Legs elevated + medicine ball."},"d-coreCirc":{"name":"Core Circuit — 4 Exercises","mus":"Full Core","cue":"Plank · Bicycle Crunches · Superman · Side Plank — back-to-back, no rest between exercises.","easy":"1 round + 1 minute full rest.","hard":"Add hollow hold as a 5th station."},"d-tabata":{"name":"Tabata — 8×20/10","mus":"Full Body","cue":"20 seconds max effort, 10 seconds rest — 8 times. One exercise per round.","easy":"30 seconds rest instead of 10.","hard":"Switch exercises every round without stopping."},"d-emom":{"name":"EMOM — Every Minute on the Minute","mus":"Full Body","cue":"At the start of every minute, complete the quota (e.g., 10 squats + 5 burpees) — the remainder of the minute is rest.","easy":"Smaller quota — 6 reps only.","hard":"Add 1 rep every minute."},"d-shuttle":{"name":"Shuttle Runs","mus":"Cardio · Agility","cue":"Hand touch on the line at every turn — no \"almosts\".","easy":"10 m distance and 45 seconds rest.","hard":"Strict rest of 20 seconds only."},"d-pace":{"name":"Paced Running Progression","mus":"Cardiovascular Endurance","cue":"First block at conversation pace, second slightly faster, third the fastest sustainable pace — not a sprint.","easy":"Brisk walking between blocks.","hard":"Only 60 seconds rest between blocks."},"d-station6":{"name":"6-Station Cardio Circuit","mus":"Full Body","cue":"Jumping jacks · High knees · Mountain climbers · Bounds · Skips · Running in place.","easy":"Walk instead of run on the hard stations.","hard":"Add burpees as a 7th station."},"d-fartlek":{"name":"Fartlek — Speed Play","mus":"Endurance","cue":"Continuous run; on the whistle accelerate for 30 seconds then return to base pace. Changes are random.","easy":"Accelerations of 15 seconds only.","hard":"45-second accelerations every minute and a half."},"d-amrap":{"name":"AMRAP — As Many Rounds As Possible","mus":"Full Body","cue":"Set list of exercises, count how many full rounds are completed in the time limit. Every student competes against themselves.","easy":"Fewer reps at each station.","hard":"Record the score and try to beat it next class."},"d-hill":{"name":"Hill Sprints","mus":"Legs · Endurance","cue":"High-intensity sprint up, walk down for recovery. Short and frequent strides.","easy":"Moderate incline and short distance.","hard":"Strict rest — depart every 60 seconds."},"d-ladder":{"name":"Agility Ladder / Hoops","mus":"Coordination · Legs","cue":"Eyes forward, not on your feet; fast and quiet feet.","easy":"Walk through the pattern before speeding up.","hard":"Lateral pattern + 180° turn at the end."},"d-tdrill":{"name":"T-Drill — Change of Direction","mus":"Agility","cue":"Sprint forward 10 m, side shuffle 5 m each way, backpedal to the start line.","easy":"Shorter distances without timing.","hard":"Photo-finish timing and personal comparison."},"d-react":{"name":"Signal Reaction","mus":"Reaction Time","cue":"Students in a ready stance; teacher gives a visual cue (hand) not auditory — sprint 10 m.","easy":"Clear auditory cue and 5 m distance.","hard":"Start from lying on the stomach, or sitting."},"d-sprint":{"name":"Short Sprints","mus":"Speed","cue":"Full recovery between sprints — train speed while fresh, not fatigued.","easy":"15 m distance at 80%.","hard":"Start from a low crouch + photo-finish timing."},"d-jump":{"name":"Basic Plyometrics","mus":"Explosive Power","cue":"Focus on the landing: quiet, knees don't cave in. Quality over quantity.","easy":"Jumping in place with no obstacle.","hard":"Depth jump from a low bench with a full stop."},"d-mirror":{"name":"Mirror Chase (Pairs)","mus":"Agility · Reaction","cue":"One leads with direction changes, the other stays tight. Swap every round.","easy":"Smaller area and slower pace.","hard":"Leader dribbles a ball."},"d-cone5":{"name":"5-Cone Drill","mus":"Agility · Coordination","cue":"5 cones in a diamond shape — sprint forward, diagonal, backward, side shuffle.","easy":"One transition at a time, walking.","hard":"Add a ball or pass at each point."},"d-fdrib":{"name":"Soccer — Dribbling and Passing","mus":"Skill","cue":"Ball close to the foot, head up between touches.","easy":"Straight path with no opponent pressure.","hard":"Two touches only, with a passive defender."},"d-fshoot":{"name":"Soccer — Finishing on Goal","mus":"Skill · Accuracy","cue":"Plant foot next to the ball, ankle locked, eyes on the ball at the moment of strike.","easy":"Stationary ball into an empty net.","hard":"Pass + two touches only + goalkeeper."},"d-bdrib":{"name":"Basketball — Two-Hand Dribbling","mus":"Skill","cue":"Fingertips not palms, head up — look at the teacher, not the ball.","easy":"Dribble in place before moving.","hard":"Two balls simultaneously, or dribble against a defender."},"d-blay":{"name":"Basketball — Layup and Shooting","mus":"Skill · Accuracy","cue":"Right-left-jump (or opposite for left), ball hits the square.","easy":"From a standstill, no steps.","hard":"After a speed dribble + passive defense."},"d-vpass":{"name":"Volleyball — Overhand and Underhand Passing","mus":"Skill","cue":"Feet under the ball before hands — movement from the legs, not arms.","easy":"Pass after a bounce on the floor.","hard":"Overhand pass only, 20 consecutive without dropping."},"d-vserve":{"name":"Volleyball — Serving","mus":"Skill · Accuracy","cue":"Consistent ball toss — most misses start with the toss, not the strike.","easy":"Underhand serve from a short distance.","hard":"Overhand serve to a marked zone, 6 out of 10."},"d-hthrow":{"name":"Handball — 3 Steps and Throw","mus":"Skill","cue":"Consistent 3-step rhythm, arm back and shoulder leads.","easy":"From a standstill into an empty net.","hard":"Jump throw over a passive defender."},"d-ult":{"name":"Ultimate — Throw and Catch","mus":"Skill","cue":"The wrist does the work — not the whole arm.","easy":"4 m distance, backhand only.","hard":"Catch on the run, against a defender."},"d-smallg":{"name":"Small-Sided Game 3×3 / 4×4","mus":"Tactics · Decision Making","cue":"Small courts = way more touches per student than an 11v11 game.","easy":"Add a neutral player who always plays for the team in possession.","hard":"Limit to two touches."},"d-keep":{"name":"Keep-away 5v2","mus":"Passing · Pressure","cue":"10 consecutive passes = 1 point. Whoever loses it goes in the middle.","easy":"6v2 in a large area.","hard":"One touch only."},"d-flow":{"name":"Mobility Flow","mus":"Full Body","cue":"Cat-Cow → Downward Dog → Lunge with twist → Deep squat → Return. Continuous movement with breath.","easy":"Pause for 3 breaths in each pose.","hard":"5-second slow movement between poses."},"d-hip":{"name":"90/90 Hip Mobility","mus":"Hips","cue":"Transition side to side without leaning on the hands, upright back.","easy":"Use hands for support and shorter range.","hard":"5-second pause on each side, hands on chest."},"d-thor":{"name":"Thoracic Rotation","mus":"Upper Back","cue":"Hips stay still — rotation comes strictly from the thoracic spine.","easy":"Seated on knees.","hard":"3-second pause at the end range + deep breath."},"d-static":{"name":"Full Static Stretches","mus":"Full Body","cue":"Only at the end of class, never as a warm-up. Breathe into the stretch, don't hold your breath.","easy":"Short range — just to a light stretch sensation.","hard":"Stretch with gentle partner assistance."},"d-coop1":{"name":"Co-op Obstacle Course","mus":"Cooperation","cue":"The whole team must cross — time stops when the last one crosses. No \"strongest takes all\".","easy":"Shorter course, fewer stations.","hard":"Constraint: 2 students hold hands throughout the course."},"d-coop2":{"name":"Team Tower","mus":"Planning · Communication","cue":"Build the tallest possible structure from the equipment — every team member must touch it at least once.","easy":"Allowed 1 minute of planning before starting.","hard":"No talking allowed — gestures only."},"d-coop3":{"name":"Timed Team Challenge","mus":"Endurance · Cohesion","cue":"Shared team quota (e.g., 200 squats) — the team decides how to split it among themselves.","easy":"Smaller quota and open time.","hard":"Large quota with a time limit."},"d-coop4":{"name":"Blindfold Partner Course","mus":"Trust · Communication","cue":"One closes their eyes, the other guides them by voice only through the course. No touching.","easy":"Straight and short course.","hard":"2 pairs on the course simultaneously — must distinguish voices."}},
  ar:{"d-squat":{"name":"سكوات بوزن الجسم","mus":"الأرجل · الألوية","cue":"الركبتان في اتجاه أصابع القدم، الصدر للأمام، نزول حتى 90°.","easy":"سكوات للمقعد — لمس وصعود.","hard":"سكوات مع قفزة، أو نزول بطيء لمدة 3 ثوانٍ."},"d-push":{"name":"تمرين الضغط","mus":"الصدر · الذراعين · المركز","cue":"الجسم كلوح واحد — الحوض لا يهبط ولا يبرز.","easy":"الأيدي على مقعد أو حائط — كلما كان أعلى، كان أسهل.","hard":"قبضة ضيقة، أو توقف لمدة ثانيتين في الأسفل."},"d-lunge":{"name":"اندفاع أمامي (لانج) مشي","mus":"الأرجل · التوازن","cue":"الركبتان بزاوية 90°، الجذع مستقيم، الركبة الخلفية لا تلمس الأرض بقوة.","easy":"اندفاع في المكان مع وضع اليد على الحائط للتوازن.","hard":"اندفاع مع قفزة تبديل، أو الإمساك بدمبل."},"d-glute":{"name":"جسر الألوية","mus":"الألوية · أسفل الظهر","cue":"الدفع من خلال الكعبين، عصر الألوية — بدون تقويس الظهر.","easy":"مدى أصغر، الثبات لمدة ثانية واحدة فقط.","hard":"رجل واحدة، أو الثبات لمدة 3 ثوانٍ في الأعلى."},"d-wall":{"name":"الجلوس على الحائط","mus":"الأرجل","cue":"الفخذان موازيان للأرض، الظهر مسطح على الحائط، الأيدي ليست على الركبتين.","easy":"زاوية أعلى — ثني أقل للركبة.","hard":"رفع رجل واحدة بالتناوب كل 5 ثوانٍ."},"d-step":{"name":"الصعود على المقعد","mus":"الأرجل · التوازن","cue":"الدفع من الرجل الموجودة على المقعد — لا تقفز من الرجل السفلية.","easy":"مقعد أقل ارتفاعًا أو درجة.","hard":"صعود مع رفع الركبة عاليًا في النهاية، أو الإمساك بدمبل."},"d-dip":{"name":"تمرين الغطس (ديبس) على المقعد","mus":"الترايسيبس · الكتفين","cue":"المرفقان للخلف وقريبان، الكتفان بعيدان عن الأذنين.","easy":"الركبتان مثنيتان، القدمان قريبتان من الجسم.","hard":"الأرجل مستقيمة ومرفوعة على مقعد آخر."},"d-pike":{"name":"ضغط بايك","mus":"الكتفين","cue":"الحوض مرتفع، الرأس ينزل بين اليدين.","easy":"الحوض أقل ارتفاعًا — أقرب لتمرين الضغط العادي.","hard":"القدمان على مقعد — تدرج للوقوف على اليدين."},"d-bear":{"name":"زحف الدب","mus":"الجسم كامل · المركز","cue":"الركبتان ترتفعان سنتيمترًا عن الأرض، الظهر مسطح.","easy":"الزحف على الركبتين.","hard":"الزحف مع كوب ماء على الظهر — دون سكبه."},"d-calf":{"name":"رفع الساقين","mus":"الساقين","cue":"صعود بطيء، ثبات لثانية في الأعلى، نزول متحكم به.","easy":"كلتا القدمين مع وضع اليد على الحائط.","hard":"رجل واحدة من حافة الدرجة."},"d-nordic":{"name":"تمرين أوتار الركبة النوردي (في أزواج)","mus":"أوتار الركبة","cue":"نزول بطيء قدر الإمكان، الأيدي مستعدة للفرملة. التمرين الذي يقلل من تمزق أوتار الركبة.","easy":"مدى قصير — النزول 20° فقط.","hard":"نزول لمدة 5 ثوانٍ حتى الأرض."},"d-sldl":{"name":"رفعة مميتة برجل واحدة (بوزن الجسم)","mus":"الألوية · التوازن","cue":"الجسم والرجل الخلفية ينزلان كلوح واحد، الحوض لا يدور.","easy":"إصبع الرجل الخلفية يلمس الأرض للتوازن.","hard":"العيون مغلقة، أو الإمساك بدمبل في اليد المقابلة."},"d-goblet":{"name":"سكوات الكأس (جوبليت)","mus":"الأرجل · المركز","cue":"الدمبل قريب من الصدر، المرفقان داخل الركبتين في الأسفل.","easy":"وزن خفيف أو بدون وزن على الإطلاق.","hard":"توقف لمدة ثانيتين في الأسفل."},"d-row":{"name":"تجديف بالدمبل","mus":"الظهر · البايسبس","cue":"المرفق يُسحب للخلف وقريب من الجسم، يتم عصر لوح الكتف في النهاية.","easy":"دعم باستخدام يد واحدة على المقعد.","hard":"تجديف بكلتا اليدين في وضع الانحناء، بدون دعم."},"d-press":{"name":"ضغط الكتفين","mus":"الكتفين · الترايسيبس","cue":"المركز مشدود — بدون تقويس أسفل الظهر.","easy":"الضغط من الجلوس مع مسند.","hard":"الضغط بيد واحدة بالتناوب — تحدي لمركز الجسم."},"d-rdl":{"name":"رفعة مميتة رومانية (RDL)","mus":"الألوية · أوتار الركبة","cue":"الفخذ يتجه للخلف، الظهر يبقى مستقيمًا — الدمبل تنزلق على الساقين.","easy":"مدى قصير حتى الركبة فقط.","hard":"رجل واحدة، أو توقف لمدة ثانيتين في الأسفل."},"d-band":{"name":"السحب بشريط المقاومة","mus":"الظهر · البايسبس","cue":"السحب يبدأ من ألواح الكتف وليس من الذراعين.","easy":"شريط أضعف أو مسكة قريبة من نقطة التثبيت.","hard":"شريط قوي + توقف لمدة ثانية في نهاية السحب."},"d-pull":{"name":"عقلة / عقلة بمساعدة","mus":"الظهر · البايسبس","cue":"سحب الصدر للبار، نزول متحكم به حتى الاستقامة الكاملة.","easy":"شريط مقاومة للمساعدة، أو تعلق أيزومتري لمدة 15 ثانية.","hard":"نزول بطيء لمدة 5 ثوانٍ (لامركزي)."},"d-kb":{"name":"أرجحة كيتل بيل","mus":"الألوية · الظهر · المركز","cue":"الحركة من الفخذين وليس من الذراعين — دفع حوض انفجاري.","easy":"الأرجحة حتى مستوى الصدر فقط، وزن خفيف.","hard":"أرجحة أمريكية حتى فوق الرأس."},"d-carry":{"name":"مشية المزارع","mus":"المركز · القبضة","cue":"الكتفان للخلف وللأسفل، خطوات صغيرة وثابتة.","easy":"وزن خفيف ومسافة قصيرة.","hard":"الوزن في يد واحدة فقط — المركز يعمل بجهد مضاعف."},"d-medball":{"name":"رمي الكرة الطبية على الحائط","mus":"الجسم كامل · قوة انفجارية","cue":"القوة تأتي من الأرجل والفخذين — الأيدي تنقلها فقط.","easy":"كرة خفيفة، رمي من الصدر فقط.","hard":"رمي من فوق الرأس بدوران، مسافة أكبر."},"d-plank":{"name":"بلانك","mus":"المركز · الكتفين","cue":"المرفقان تحت الكتفين، البطن مشدودة، تنفس مستمر.","easy":"بلانك على الركبتين أو بميل على مقعد.","hard":"رفع يد أو رجل بالتناوب كل 5 ثوانٍ."},"d-splank":{"name":"بلانك جانبي","mus":"المركز · العضلات المائلة","cue":"خط مستقيم من الرأس للكاحل — الحوض لا يسقط ولا يبرز.","easy":"الركبة السفلية على الأرض.","hard":"رفع الرجل العلوية، أو خفض ورفع الحوض ×10."},"d-deadbug":{"name":"الحشرة الميتة (Dead bug)","mus":"المركز · الثبات","cue":"أسفل الظهر ملتصق بالأرض طوال التمرين.","easy":"الأرجل فقط، الأيدي تبقى في الأعلى.","hard":"حركة لمدة 4 ثوانٍ لكل تكرار."},"d-birddog":{"name":"كلب الطير (Bird dog)","mus":"المركز · الثبات","cue":"الحوض لا يدور — يد ورجل متقابلتان تمتدان معًا.","easy":"الرجل فقط، بدون يد.","hard":"توقف لمدة 3 ثوانٍ + لمس المرفق للركبة بين التكرارات."},"d-hollow":{"name":"الثبات المجوف (Hollow hold)","mus":"البطن","cue":"أسفل الظهر ملتصق بالأرض — إذا ارتفع، نقصر الرافعة.","easy":"الركبتان مثنيتان، الأيدي بجانب الجسم.","hard":"الأيدي فوق الرأس والأرجل مستقيمة ومنخفضة."},"d-bicycle":{"name":"طحن الدراجة","mus":"البطن · العضلات المائلة","cue":"المرفق يقابل الركبة العكسية ببطء — دون سحب الرقبة.","easy":"دوران الجزء العلوي فقط، الأقدام على الأرض.","hard":"حركة لمدة 3 ثوانٍ لكل جانب."},"d-superman":{"name":"سوبرمان","mus":"أسفل الظهر","cue":"رفع اليدين والرجلين معًا، النظر للأرض — الرقبة في مستوى الظهر.","easy":"يد ورجل متقابلتان فقط.","hard":"الثبات لمدة 3 ثوانٍ في كل تكرار."},"d-rtwist":{"name":"الدوران الروسي","mus":"البطن · العضلات المائلة","cue":"الدوران يأتي من القفص الصدري، وليس فقط من اليدين.","easy":"الأقدام على الأرض، بدون كرة.","hard":"الأرجل مرفوعة + كرة طبية."},"d-coreCirc":{"name":"دائرة المركز — 4 تمارين","mus":"المركز بالكامل","cue":"بلانك · طحن الدراجة · سوبرمان · بلانك جانبي — بتسلسل، بدون راحة بين التمارين.","easy":"دورة واحدة + دقيقة راحة كاملة.","hard":"إضافة الثبات المجوف كمحطة خامسة."},"d-tabata":{"name":"تاباتا — 8×20/10","mus":"الجسم كامل","cue":"20 ثانية بأقصى جهد، 10 ثوانٍ راحة — 8 مرات. تمرين واحد لكل دورة.","easy":"30 ثانية راحة بدلاً من 10.","hard":"تبديل التمرين في كل دورة، بدون توقف."},"d-emom":{"name":"EMOM — في كل دقيقة على مدار الساعة","mus":"الجسم كامل","cue":"في بداية كل دقيقة ننفذ الحصة (مثلاً 10 سكوات + 5 بيربي) — ما يتبقى من الدقيقة هو الراحة.","easy":"حصة أصغر — 6 تكرارات فقط.","hard":"إضافة تكرار واحد في كل دقيقة."},"d-shuttle":{"name":"الجري المكوكي (Shuttle)","mus":"كارديو · رشاقة","cue":"لمس الخط باليد في كل دورة — لا توجد استثناءات.","easy":"مسافة 10 م وراحة لمدة 45 ثانية.","hard":"راحة محددة بـ 20 ثانية فقط."},"d-pace":{"name":"الجري بإيقاع متدرج","mus":"التحمل القلبي التنفسي","cue":"المجموعة الأولى بإيقاع المحادثة، الثانية أسرع قليلاً، الثالثة أسرع إيقاع يمكن الحفاظ عليه — وليس سباق سرعة.","easy":"مشي سريع بين المجموعات.","hard":"راحة لمدة 60 ثانية فقط بين المجموعات."},"d-station6":{"name":"دائرة كارديو 6 محطات","mus":"الجسم كامل","cue":"قفز مع فتح وضم الرجلين · ركب عالية · متسلق الجبال · وثب · تخطي · جري في المكان.","easy":"مشي بدلاً من الجري في المحطات الصعبة.","hard":"إضافة بيربي كمحطة سابعة."},"d-fartlek":{"name":"فارتلك — لعبة السرعة","mus":"التحمل","cue":"جري مستمر؛ عند الصافرة نسرع لمدة 30 ثانية ثم نعود للإيقاع الأساسي. التغييرات عشوائية.","easy":"تسارعات لمدة 15 ثانية فقط.","hard":"تسارعات لمدة 45 ثانية كل دقيقة ونصف."},"d-amrap":{"name":"AMRAP — أكبر عدد ممكن من الجولات","mus":"الجسم كامل","cue":"قائمة تمارين ثابتة، ونحسب كم جولة كاملة ننجزها في الوقت المحدد. كل طالب ينافس نفسه.","easy":"عدد تكرارات أقل في كل محطة.","hard":"تسجيل النتيجة ومحاولة تحسينها في الدرس القادم."},"d-hill":{"name":"جري التلال","mus":"الأرجل · التحمل","cue":"صعود بكثافة عالية، نزول بالمشي كراحة. خطوات قصيرة ومتكررة.","easy":"ميل معتدل ومسافة قصيرة.","hard":"راحة محددة — الانطلاق كل 60 ثانية."},"d-ladder":{"name":"سلم الرشاقة / أطواق","mus":"التوافق · الأرجل","cue":"النظر للأمام وليس للقدمين، أقدام سريعة وهادئة.","easy":"مشي عبر النمط قبل التسريع.","hard":"نمط جانبي + دوران 180° في النهاية."},"d-tdrill":{"name":"تمرين T — تغيير الاتجاه","mus":"الرشاقة","cue":"جري للأمام 10 م، انزلاق جانبي 5 م لكل جانب، جري للخلف لنقطة البداية.","easy":"مسافات صغيرة وبدون قياس للوقت.","hard":"قياس بالصورة النهائية (فوتو-فينيش) ومقارنة شخصية."},"d-react":{"name":"التفاعل مع الإشارة","mus":"سرعة رد الفعل","cue":"الطلاب في وضع الاستعداد؛ المعلم يعطي إشارة بصرية (باليد) وليس صوتية — تسارع 10 م.","easy":"إشارة صوتية واضحة ومسافة 5 م.","hard":"الانطلاق من الاستلقاء على البطن، أو الجلوس."},"d-sprint":{"name":"تسارعات قصيرة","mus":"السرعة","cue":"راحة كاملة بين التسارعات — نتدرب على السرعة ونحن بكامل طاقتنا، ليس ونحن متعبون.","easy":"مسافة 15 م بنسبة 80%.","hard":"الانطلاق من وضع منخفض + قياس بالصورة النهائية."},"d-jump":{"name":"بليومتريكس أساسي","mus":"القوة الانفجارية","cue":"التركيز على الهبوط: هادئ، الركبتان لا تنهاران للداخل. الجودة قبل الكمية.","easy":"قفز في المكان بدون حاجز.","hard":"قفز عميق من مقعد منخفض مع توقف كامل."},"d-mirror":{"name":"مطاردة في أزواج (المرآة)","mus":"الرشاقة · رد الفعل","cue":"أحدهما يقود بتغيير الاتجاه، والآخر يبقى قريبًا. تبديل كل جولة.","easy":"مساحة أصغر وإيقاع أبطأ.","hard":"القائد ينطط الكرة."},"d-cone5":{"name":"مسار الـ 5 أقماع","mus":"الرشاقة · التوافق","cue":"5 أقماع على شكل ماسة — جري للأمام، قطري، للخلف، انزلاق جانبي.","easy":"انتقال واحد في كل مرة، مشي.","hard":"إضافة كرة أو تمريرة عند كل نقطة."},"d-fdrib":{"name":"كرة قدم — تنطيط (مراوغة) وتمرير","mus":"المهارة","cue":"الكرة قريبة من القدم، الرأس مرفوع بين اللمسة والأخرى.","easy":"مسار مستقيم بدون ضغط من خصم.","hard":"لمستان فقط، مع مدافع سلبي."},"d-fshoot":{"name":"كرة قدم — إنهاء نحو المرمى","mus":"المهارة · الدقة","cue":"قدم الارتكاز بجانب الكرة، الكاحل مشدود، النظر للكرة لحظة الركل.","easy":"كرة ثابتة نحو مرمى فارغ.","hard":"تمريرة + لمستان فقط + حارس مرمى."},"d-bdrib":{"name":"كرة سلة — تنطيط باليدين","mus":"المهارة","cue":"بأطراف الأصابع وليس بكف اليد، الرأس مرفوع — النظر للمعلم وليس للكرة.","easy":"تنطيط في المكان قبل التقدم.","hard":"كرتان في نفس الوقت، أو تنطيط ضد مدافع."},"d-blay":{"name":"كرة سلة — رمية سلمية (Layup) وتصويب","mus":"المهارة · الدقة","cue":"يمين-يسار-قفز (أو العكس لليسار)، الكرة تضرب في المربع.","easy":"من المكان، بدون خطوات.","hard":"بعد تنطيط سريع + دفاع سلبي."},"d-vpass":{"name":"كرة طائرة — تمرير علوي وسفلي","mus":"المهارة","cue":"الأقدام تحت الكرة قبل اليدين — الحركة من الأرجل وليس من الذراعين.","easy":"تمرير بعد ارتداد الكرة من الأرض.","hard":"تمرير علوي فقط، 20 مرة متتالية بدون سقوط."},"d-vserve":{"name":"كرة طائرة — إرسال","mus":"المهارة · الدقة","cue":"رمية كرة ثابتة — معظم الأخطاء تبدأ في الرمية وليس في الضربة.","easy":"إرسال من الأسفل، من مسافة قصيرة.","hard":"إرسال من الأعلى لمنطقة محددة، 6 من أصل 10."},"d-hthrow":{"name":"كرة يد — 3 خطوات ورمي","mus":"المهارة","cue":"إيقاع 3 خطوات ثابت، الذراع للخلف والكتف يقود الحركة.","easy":"من المكان، لمرمى فارغ.","hard":"رمي مع القفز فوق مدافع سلبي."},"d-ult":{"name":"ألتيميت — رمي والتقاط","mus":"المهارة","cue":"معصم اليد يقوم بالعمل — ليس الذراع بأكملها.","easy":"مسافة 4 م، رمية خلفية (باكهاند) فقط.","hard":"التقاط أثناء الجري، مع وجود مدافع."},"d-smallg":{"name":"لعبة مصغرة 3×3 / 4×4","mus":"التكتيك · اتخاذ القرار","cue":"ملاعب صغيرة = لمسات أكثر بكثير لكل طالب مقارنة بلعبة 11 ضد 11.","easy":"إضافة لاعب محايد يلعب دائمًا مع الفريق المستحوذ.","hard":"تحديد بلمستين فقط."},"d-keep":{"name":"الاحتفاظ بالكرة 5 ضد 2","mus":"التمرير · الضغط","cue":"10 تمريرات متتالية = نقطة. من يفقد الكرة يدخل للوسط.","easy":"6 ضد 2 في مساحة كبيرة.","hard":"لمسة واحدة فقط."},"d-flow":{"name":"تسلسل حركي (Flow)","mus":"الجسم كامل","cue":"القطة-البقرة → الكلب المواجه للأسفل → اندفاع مع دوران → جلوس عميق → العودة. حركة مستمرة مع التنفس.","easy":"توقف لـ 3 أنفاس في كل وضعية.","hard":"حركة بطيئة لمدة 5 ثوانٍ بين الوضعيات."},"d-hip":{"name":"حركية الوركين 90/90","mus":"الوركين","cue":"انتقال من جانب لآخر دون الاستناد على اليدين، الظهر مستقيم.","easy":"الاستعانة باليدين ومدى حركي قصير.","hard":"توقف لمدة 5 ثوانٍ في كل جانب، الأيدي على الصدر."},"d-thor":{"name":"دوران القفص الصدري","mus":"أعلى الظهر","cue":"الحوض لا يتحرك — الدوران يأتي فقط من القفص الصدري.","easy":"بالجلوس على الركبتين.","hard":"توقف لمدة 3 ثوانٍ في النهاية + نفس عميق."},"d-static":{"name":"إطالات ثابتة كاملة","mus":"الجسم كامل","cue":"فقط في نهاية الدرس، وليس أبدًا كإحماء. تنفس مع الإطالة، لا تحبس الهواء.","easy":"مدى صغير — حتى الشعور بإطالة خفيفة فقط.","hard":"إطالة بمساعدة لطيفة من الزميل."},"d-coop1":{"name":"مسار الحواجز التعاوني","mus":"التعاون","cue":"المجموعة كلها يجب أن تعبر — الوقت يتوقف عندما يعبر الأخير. لا يوجد \"الأقوى يأخذ كل شيء\".","easy":"مسار أقصر، محطات أقل.","hard":"قيد: طالبان متصلان بالأيدي طوال المسار."},"d-coop2":{"name":"برج الفريق","mus":"التخطيط · التواصل","cue":"بناء أطول هيكل ممكن من المعدات — يجب على كل عضو في الفريق لمسه مرة واحدة على الأقل.","easy":"يسمح بالتخطيط لمدة دقيقة قبل البدء.","hard":"ممنوع التحدث — الإشارات فقط."},"d-coop3":{"name":"تحدي الفريق الزمني","mus":"التحمل · التماسك","cue":"حصة جماعية مشتركة (مثلاً 200 سكوات) — الفريق يقرر كيف يوزعها بينهم.","easy":"حصة أصغر ووقت مفتوح.","hard":"حصة كبيرة مع وقت محدد."},"d-coop4":{"name":"المسار الأعمى في أزواج","mus":"الثقة · التواصل","cue":"أحدهما يغمض عينيه، والآخر يوجهه بالصوت فقط عبر المسار. لا يوجد تلامس.","easy":"مسار مستقيم وقصير.","hard":"زوجان في المسار في نفس الوقت — يجب التمييز بين الأصوات."}},
  ru:{"d-squat":{"name":"Приседания с весом тела","mus":"Ноги · Ягодицы","cue":"Колени направлены вдоль носков, грудь вперед, опускание до 90°.","easy":"Приседания на скамью — касание и подъем.","hard":"Приседания с выпрыгиванием или медленное опускание за 3 секунды."},"d-push":{"name":"Отжимания","mus":"Грудь · Руки · Кор","cue":"Тело как одна прямая линия — таз не провисает и не выпячивается.","easy":"Руки на скамье или стене — чем выше, тем легче.","hard":"Узкий хват или пауза на 2 секунды внизу."},"d-lunge":{"name":"Выпады в ходьбе","mus":"Ноги · Равновесие","cue":"Оба колена под углом 90°, туловище прямое, заднее колено не бьется об пол.","easy":"Выпады на месте с рукой на стене для баланса.","hard":"Выпады с прыжком-сменой ног или с гантелями."},"d-glute":{"name":"Ягодичный мостик","mus":"Ягодицы · Поясница","cue":"Упор на пятки, сжимаем ягодицы — без прогиба в пояснице.","easy":"Меньшая амплитуда, задержка только на 1 секунду.","hard":"На одной ноге или удержание 3 секунды в верхней точке."},"d-wall":{"name":"Стульчик у стены","mus":"Ноги","cue":"Бедра параллельны полу, спина прижата к стене, руки не на коленях.","easy":"Выше угол — меньше сгибание в коленях.","hard":"Поочередный подъем одной ноги каждые 5 секунд."},"d-step":{"name":"Зашагивания на скамью","mus":"Ноги · Равновесие","cue":"Толчок ногой, стоящей на скамье — не отталкиваться нижней ногой.","easy":"Низкая скамья или ступенька.","hard":"Зашагивание с высоким подъемом колена в конце или с гантелью."},"d-dip":{"name":"Обратные отжимания от скамьи","mus":"Трицепс · Плечи","cue":"Локти назад и прижаты к телу, плечи опущены от ушей.","easy":"Колени согнуты, ноги ближе к телу.","hard":"Прямые ноги подняты на вторую скамью."},"d-pike":{"name":"Отжимания щукой (Pike push-ups)","mus":"Плечи","cue":"Таз высоко, голова опускается между руками.","easy":"Таз ниже — ближе к обычным отжиманиям.","hard":"Ноги на скамье — подводящее упражнение к стойке на руках."},"d-bear":{"name":"Медвежья проходка","mus":"Все тело · Кор","cue":"Колени парят в сантиметре от пола, спина прямая.","easy":"Перемещение на коленях.","hard":"Проходка со стаканом воды на спине — не пролить."},"d-calf":{"name":"Подъемы на носки","mus":"Икры","cue":"Медленный подъем, 1 секунда паузы вверху, подконтрольное опускание.","easy":"На двух ногах с упором рукой о стену.","hard":"На одной ноге с края ступеньки."},"d-nordic":{"name":"Скандинавские сгибания (в парах)","mus":"Бицепс бедра","cue":"Опускаться как можно медленнее, руки готовы для торможения. Главное упражнение для снижения травм бицепса бедра.","easy":"Короткая амплитуда — опускание только на 20°.","hard":"Опускание за 5 секунд до пола."},"d-sldl":{"name":"Румынская тяга на одной ноге (вес тела)","mus":"Ягодицы · Равновесие","cue":"Тело и задняя нога опускаются как единая линия, таз не разворачивается.","easy":"Носок задней ноги касается пола для баланса.","hard":"С закрытыми глазами или с гантелью в противоположной руке."},"d-goblet":{"name":"Гоблет-приседания","mus":"Ноги · Кор","cue":"Гантель прижата к груди, локти внутри коленей в нижней точке.","easy":"Легкий вес или без веса.","hard":"Пауза 2 секунды в нижней точке."},"d-row":{"name":"Тяга гантели в наклоне","mus":"Спина · Бицепс","cue":"Локоть отводится назад и прижат к телу, лопатка сводится в верхней точке.","easy":"С опорой одной рукой на скамью.","hard":"Тяга двумя руками в наклоне, без опоры."},"d-press":{"name":"Жим гантелей стоя","mus":"Плечи · Трицепс","cue":"Кор напряжен — без прогиба в пояснице.","easy":"Жим сидя со спинкой.","hard":"Поочередный жим одной рукой — вызов для кора."},"d-rdl":{"name":"Румынская тяга (RDL)","mus":"Ягодицы · Бицепс бедра","cue":"Таз отводится назад, спина прямая — гантели скользят по ногам.","easy":"Короткая амплитуда, только до колен.","hard":"На одной ноге или пауза 2 секунды в нижней точке."},"d-band":{"name":"Тяга эспандера","mus":"Спина · Бицепс","cue":"Тяга начинается от лопаток, а не от рук.","easy":"Слабый эспандер или хват ближе к месту крепления.","hard":"Сильный эспандер + пауза на 1 секунду в конце тяги."},"d-pull":{"name":"Подтягивания / С помощью","mus":"Спина · Бицепс","cue":"Тянем грудь к перекладине, подконтрольное опускание до полного выпрямления.","easy":"Помощь эспандера или изометрический вис 15 секунд.","hard":"Медленное опускание за 5 секунд (эксцентрика)."},"d-kb":{"name":"Махи гирей (Свинг)","mus":"Ягодицы · Спина · Кор","cue":"Движение от бедер, а не от рук — взрывной толчок тазом.","easy":"Махи только до уровня груди, легкий вес.","hard":"Американские махи до положения над головой."},"d-carry":{"name":"Прогулка фермера","mus":"Кор · Хват","cue":"Плечи назад и вниз, короткие уверенные шаги.","easy":"Легкий вес и короткая дистанция.","hard":"Вес только в одной руке — кор работает вдвойне."},"d-medball":{"name":"Броски набивного мяча в стену","mus":"Все тело · Взрывная сила","cue":"Сила идет от ног и бедер — руки лишь передают ее.","easy":"Легкий мяч, броски только от груди.","hard":"Броски из-за головы с вращением, большая дистанция."},"d-plank":{"name":"Планка","mus":"Кор · Плечи","cue":"Локти под плечами, живот втянут, непрерывное дыхание.","easy":"Планка на коленях или под наклоном на скамье.","hard":"Поочередный подъем руки или ноги каждые 5 секунд."},"d-splank":{"name":"Боковая планка","mus":"Кор · Косые мышцы","cue":"Прямая линия от головы до лодыжек — таз не провисает и не выпячивается.","easy":"Нижнее колено на полу.","hard":"Подъем верхней ноги или опускание и подъем таза ×10."},"d-deadbug":{"name":"Мертвый жук (Dead bug)","mus":"Кор · Стабильность","cue":"Поясница прижата к полу на протяжении всего упражнения.","easy":"Только ноги, руки остаются вверху.","hard":"Движение по 4 секунды на каждое повторение."},"d-birddog":{"name":"Птица-собака (Bird dog)","mus":"Кор · Стабильность","cue":"Таз не разворачивается — противоположные рука и нога вытягиваются вместе.","easy":"Только нога, без руки.","hard":"Пауза 3 секунды + касание локтем колена между повторениями."},"d-hollow":{"name":"Удержание «Лодочка» (Hollow hold)","mus":"Пресс","cue":"Поясница прижата к полу — если она отрывается, укоротите рычаг.","easy":"Колени согнуты, руки вдоль тела.","hard":"Руки за головой, прямые ноги опущены низко."},"d-bicycle":{"name":"Скручивания «Велосипед»","mus":"Пресс · Косые мышцы","cue":"Локоть медленно встречается с противоположным коленом — без рывков за шею.","easy":"Только повороты туловища, стопы на полу.","hard":"Движение по 3 секунды в каждую сторону."},"d-superman":{"name":"Супермен","mus":"Поясница","cue":"Поднимаем руки и ноги вместе, взгляд в пол — шея на одной линии со спиной.","easy":"Только противоположные рука и нога.","hard":"Удержание 3 секунды на каждом повторении."},"d-rtwist":{"name":"Русские скручивания","mus":"Пресс · Косые мышцы","cue":"Вращение исходит от грудной клетки, а не только от рук.","easy":"Стопы на полу, без мяча.","hard":"Ноги подняты + набивной мяч."},"d-coreCirc":{"name":"Круг на кор — 4 упражнения","mus":"Весь кор","cue":"Планка · Велосипед · Супермен · Боковая планка — подряд, без отдыха между упражнениями.","easy":"1 круг + полный отдых 1 минута.","hard":"Добавить удержание «Лодочка» как пятую станцию."},"d-tabata":{"name":"Табата — 8×20/10","mus":"Все тело","cue":"20 секунд максимального усилия, 10 секунд отдыха — 8 раз. Одно упражнение на раунд.","easy":"30 секунд отдыха вместо 10.","hard":"Смена упражнения каждый раунд без остановок."},"d-emom":{"name":"EMOM — Каждую минуту","mus":"Все тело","cue":"В начале каждой минуты выполняем норму (например, 10 приседаний + 5 берпи) — оставшееся время минуты отдыхаем.","easy":"Меньшая норма — только 6 повторений.","hard":"Добавлять 1 повторение каждую минуту."},"d-shuttle":{"name":"Челночный бег","mus":"Кардио · Ловкость","cue":"Касание линии рукой при каждом повороте — никаких «почти».","easy":"Дистанция 10 м и отдых 45 секунд.","hard":"Строгий отдых ровно 20 секунд."},"d-pace":{"name":"Темповой бег по нарастающей","mus":"Сердечно-сосудистая выносливость","cue":"Первый блок в разговорном темпе, второй чуть быстрее, третий — максимально быстрый, который можно поддерживать (не спринт).","easy":"Быстрая ходьба между блоками.","hard":"Отдых всего 60 секунд между блоками."},"d-station6":{"name":"Кардио-круг на 6 станций","mus":"Все тело","cue":"Джампинг джек · Бег с высоким подниманием бедра · Скалолаз · Прыжки · Скипы · Бег на месте.","easy":"Ходьба вместо бега на сложных станциях.","hard":"Добавить берпи как 7-ю станцию."},"d-fartlek":{"name":"Фартлек — Игры со скоростью","mus":"Выносливость","cue":"Непрерывный бег; по свистку ускорение на 30 секунд, затем возврат к базовому темпу. Смена случайная.","easy":"Ускорения всего по 15 секунд.","hard":"Ускорения по 45 секунд каждые полторы минуты."},"d-amrap":{"name":"AMRAP — Как можно больше раундов","mus":"Все тело","cue":"Заданный список упражнений, считаем количество полных кругов за отведенное время. Каждый соревнуется с самим собой.","easy":"Меньшее количество повторений на каждой станции.","hard":"Записать результат и постараться улучшить на следующем уроке."},"d-hill":{"name":"Бег в гору","mus":"Ноги · Выносливость","cue":"Забегание высокой интенсивности, спуск шагом для восстановления. Шаги короткие и частые.","easy":"Умеренный уклон и короткая дистанция.","hard":"Строгий отдых — старт каждые 60 секунд."},"d-ladder":{"name":"Координационная лестница / Обручи","mus":"Координация · Ноги","cue":"Взгляд вперед, а не под ноги; быстрые и тихие шаги.","easy":"Пройти схему шагом перед ускорением.","hard":"Движение боком + поворот на 180° в конце."},"d-tdrill":{"name":"Т-тест — Смена направления","mus":"Ловкость","cue":"Спринт вперед 10 м, приставной шаг 5 м в каждую сторону, бег спиной вперед к линии старта.","easy":"Меньшие дистанции и без учета времени.","hard":"Замер по фотофинишу и личное сравнение."},"d-react":{"name":"Реакция на сигнал","mus":"Скорость реакции","cue":"Ученики в стойке готовности; учитель дает визуальный сигнал (рукой), а не звуковой — ускорение на 10 м.","easy":"Четкий звуковой сигнал и дистанция 5 м.","hard":"Старт из положения лежа на животе или сидя."},"d-sprint":{"name":"Короткие спринты","mus":"Скорость","cue":"Полное восстановление между спринтами — скорость тренируют свежими, а не уставшими.","easy":"Дистанция 15 м на 80% усилий.","hard":"Старт из низкого приседа + замер по фотофинишу."},"d-jump":{"name":"Базовая плиометрика","mus":"Взрывная сила","cue":"Внимание на приземление: тихое, колени не заваливаются внутрь. Качество важнее количества.","easy":"Прыжки на месте без препятствий.","hard":"Прыжок в глубину с низкой скамьи с полной остановкой."},"d-mirror":{"name":"Преследование в парах (Зеркало)","mus":"Ловкость · Реакция","cue":"Один ведет, меняя направление, второй держится рядом. Смена каждый раунд.","easy":"Меньшая площадь и более медленный темп.","hard":"Ведущий ведет мяч (дриблинг)."},"d-cone5":{"name":"Квадрат из 5 конусов","mus":"Ловкость · Координация","cue":"5 конусов ромбом — спринт вперед, по диагонали, спиной, приставным шагом.","easy":"По одному переходу за раз, шагом.","hard":"Добавить мяч или передачу на каждой точке."},"d-fdrib":{"name":"Футбол — Ведение и передача","mus":"Навык","cue":"Мяч близко к ноге, голова поднята между касаниями.","easy":"Прямая траектория без давления соперника.","hard":"Только два касания, с пассивным защитником."},"d-fshoot":{"name":"Футбол — Удары по воротам","mus":"Навык · Точность","cue":"Опорная нога рядом с мячом, голеностоп зафиксирован, взгляд на мяч в момент удара.","easy":"Неподвижный мяч по пустым воротам.","hard":"Пас + только два касания + вратарь."},"d-bdrib":{"name":"Баскетбол — Ведение двумя руками","mus":"Навык","cue":"Подушечками пальцев, а не ладонью, голова поднята — смотрим на учителя, а не на мяч.","easy":"Ведение на месте перед движением.","hard":"Два мяча одновременно или ведение против защитника."},"d-blay":{"name":"Баскетбол — Лей-ап и бросок","mus":"Навык · Точность","cue":"Правой-левой-прыжок (или наоборот слева), мяч бьется в квадрат.","easy":"С места, без шагов.","hard":"После скоростного ведения + пассивная защита."},"d-vpass":{"name":"Волейбол — Передача сверху и снизу","mus":"Навык","cue":"Ноги под мяч раньше рук — движение от ног, а не от рук.","easy":"Передача после отскока от пола.","hard":"Только верхняя передача, 20 раз подряд без падений."},"d-vserve":{"name":"Волейбол — Подача","mus":"Навык · Точность","cue":"Стабильный подброс — большинство промахов начинается с подброса, а не с удара.","easy":"Нижняя подача с короткой дистанции.","hard":"Верхняя подача в размеченную зону, 6 из 10."},"d-hthrow":{"name":"Гандбол — 3 шага и бросок","mus":"Навык","cue":"Стабильный ритм 3 шагов, рука отведена назад, плечо ведет.","easy":"С места, по пустым воротам.","hard":"Бросок в прыжке через пассивного защитника."},"d-ult":{"name":"Алтимат — Бросок и ловля","mus":"Навык","cue":"Работает запястье — не вся рука.","easy":"Дистанция 4 м, только бэкхенд.","hard":"Ловля на бегу, с защитником."},"d-smallg":{"name":"Мини-игра 3×3 / 4×4","mus":"Тактика · Принятие решений","cue":"Малые площадки = гораздо больше касаний у каждого ученика, чем в игре 11 на 11.","easy":"Добавить нейтрального игрока, который всегда играет за владеющую команду.","hard":"Ограничение в два касания."},"d-keep":{"name":"Удержание мяча 5 на 2","mus":"Передача · Прессинг","cue":"10 точных пасов подряд = 1 очко. Потерявший идет в центр.","easy":"6 на 2 на большой площади.","hard":"Только одно касание."},"d-flow":{"name":"Подвижный поток (Flow)","mus":"Все тело","cue":"Кошка-корова → Собака мордой вниз → Выпад со скручиванием → Глубокий присед → Возврат. Непрерывное движение с дыханием.","easy":"Пауза на 3 вдоха-выдоха в каждой позе.","hard":"Медленное движение по 5 секунд между позами."},"d-hip":{"name":"Мобильность бедер 90/90","mus":"Тазобедренные суставы","cue":"Переход со стороны в сторону без опоры на руки, спина прямая.","easy":"Помогать руками и короткая амплитуда.","hard":"Пауза по 5 секунд на каждой стороне, руки на груди."},"d-thor":{"name":"Вращение грудного отдела","mus":"Верхняя часть спины","cue":"Таз не двигается — вращение происходит только в грудном отделе.","easy":"Сидя на коленях.","hard":"Пауза на 3 секунды в крайней точке + глубокий вдох."},"d-static":{"name":"Полная статическая растяжка","mus":"Все тело","cue":"Только в конце урока, никогда вместо разминки. Дышим при растяжении, не задерживаем дыхание.","easy":"Короткая амплитуда — только до легкого чувства натяжения.","hard":"Растяжка с легкой помощью партнера."},"d-coop1":{"name":"Полоса препятствий вместе","mus":"Сотрудничество","cue":"Вся команда должна пройти — время останавливается, когда прошел последний. Никаких «побеждает сильнейший».","easy":"Более короткая трасса, меньше станций.","hard":"Ограничение: два ученика держатся за руки на всей дистанции."},"d-coop2":{"name":"Командная башня","mus":"Планирование · Коммуникация","cue":"Построить максимально высокую конструкцию из инвентаря — каждый член команды должен коснуться её хотя бы раз.","easy":"Разрешена 1 минута на планирование до старта.","hard":"Запрещено говорить — только жесты."},"d-coop3":{"name":"Командный вызов на время","mus":"Выносливость · Сплоченность","cue":"Общая командная норма (например, 200 приседаний) — команда сама решает, как распределить их между собой.","easy":"Меньшая норма и неограниченное время.","hard":"Большая норма с ограничением по времени."},"d-coop4":{"name":"Слепая трасса в парах","mus":"Доверие · Коммуникация","cue":"Один закрывает глаза, другой ведет его только голосом по трассе. Без касаний.","easy":"Прямая и короткая трасса.","hard":"2 пары на трассе одновременно — нужно различать голоса."}},
};
const MAIN_FORMATS_I18N={
  en:{"stations":{"name":"Stations","d":"Each exercise gets its own station, the class rotates. Best for large classes with limited equipment."},"circuit":{"name":"Circuit Training","d":"All exercises back-to-back, then rest and another round. High intensity and minimal dead time."},"sets":{"name":"Sets and Reps","d":"Work exercise by exercise, finishing all sets before moving on. Best for technique learning and gym settings."},"pairs":{"name":"Pair Work","d":"One works, the other counts and gives technique feedback — then swap. Teaches evaluation."},"amrap":{"name":"AMRAP — As Many Rounds As Possible","d":"Set list of exercises and set time. Every student competes against themselves, no class comparison."},"emom":{"name":"EMOM — Every Minute on the Minute","d":"Set quota at the start of each minute; the remainder is rest. Teaches pacing."},"free":{"name":"Guided Free Practice","d":"Students choose what to work on from the list, the teacher walks around giving individual feedback."}},
  ar:{"stations":{"name":"محطات","d":"كل تمرين في محطة خاصة، الفصل يدور. الأنسب لفصل كبير بمعدات قليلة."},"circuit":{"name":"دائرة تدريبية","d":"كل التمارين متتالية، ثم راحة وجولة أخرى. كثافة عالية ووقت ضائع بالحد الأدنى."},"sets":{"name":"مجموعات وتكرارات","d":"العمل تمرينًا بتمرين، كل واحد حتى النهاية. الأنسب لتعليم التكنيك وفي صالة الألعاب الرياضية."},"pairs":{"name":"عمل في أزواج","d":"أحدهما يعمل، والآخر يعد ويعطي ملاحظات على التكنيك — ثم يتبادلان. يتعلمون التقييم أيضًا."},"amrap":{"name":"AMRAP — أكبر عدد ممكن من الجولات","d":"قائمة تمارين ثابتة ووقت ثابت. كل طالب ينافس نفسه، بدون مقارنة مع الفصل."},"emom":{"name":"EMOM — في كل دقيقة على مدار الساعة","d":"حصة ثابتة في بداية كل دقيقة؛ ما يتبقى هو الراحة. يُعلم إدارة الإيقاع."},"free":{"name":"تدريب حر موجه","d":"يختار الطلاب ما يريدون التدرب عليه من القائمة، ويمر المعلم لإعطاء ملاحظات شخصية."}},
  ru:{"stations":{"name":"Станции","d":"Каждое упражнение на своей станции, класс меняется по кругу. Лучше всего для больших классов с минимумом инвентаря."},"circuit":{"name":"Круговая тренировка","d":"Все упражнения подряд, затем отдых и следующий круг. Высокая интенсивность и минимум простоев."},"sets":{"name":"Сеты и повторения","d":"Выполняем упражнение за упражнением, каждый до конца. Лучше всего для изучения техники и в тренажерном зале."},"pairs":{"name":"Работа в парах","d":"Один работает, другой считает и дает отзыв по технике — затем меняются. Также учит оценивать."},"amrap":{"name":"AMRAP — Как можно больше раундов","d":"Заданный список упражнений и фиксированное время. Каждый соревнуется сам с собой, без сравнений с классом."},"emom":{"name":"EMOM — Каждую минуту","d":"Заданная норма в начале каждой минуты; оставшееся время — отдых. Учит управлять темпом."},"free":{"name":"Управляемая свободная практика","d":"Ученики сами выбирают, над чем работать из списка, учитель ходит и дает персональные советы."}},
};
